package com.srinu.otelpoc.customer.service; import com.srinu.otelpoc.customer.domain.Customer; import com.srinu.otelpoc.customer.repository.CustomerRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service public class CustomerApplicationService { private final CustomerRepository repo; public CustomerApplicationService(CustomerRepository r){repo=r;} public List<Customer> list(){return repo.findAll();} public Customer get(String id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("customer not found"));} @Transactional public Customer create(Customer c){return repo.save(c);} @Transactional public Customer update(String id,String n,String e,String a){var c=get(id);c.update(n,e,a);return c;} @Transactional public void deactivate(String id){get(id).deactivate();} }
